import pytest
import time
from retry import retry


def test_succeeds_first_try():
    calls = []
    @retry(max_attempts=3)
    def f():
        calls.append(1)
        return "ok"
    assert f() == "ok"
    assert len(calls) == 1


def test_retries_on_failure():
    calls = []
    @retry(max_attempts=3, delay=0)
    def f():
        calls.append(1)
        if len(calls) < 3:
            raise ValueError("not yet")
        return "done"
    assert f() == "done"
    assert len(calls) == 3


def test_raises_after_max_attempts():
    @retry(max_attempts=2, delay=0)
    def f():
        raise RuntimeError("always fails")
    with pytest.raises(RuntimeError, match="always fails"):
        f()


def test_max_attempts_one_never_retries():
    calls = []
    @retry(max_attempts=1, delay=0)
    def f():
        calls.append(1)
        raise ValueError("fail")
    with pytest.raises(ValueError):
        f()
    assert len(calls) == 1


def test_exponential_backoff(monkeypatch):
    slept = []
    monkeypatch.setattr(time, "sleep", lambda s: slept.append(s))
    @retry(max_attempts=3, delay=1.0, backoff=2.0)
    def f():
        raise ValueError("fail")
    with pytest.raises(ValueError):
        f()
    # First retry: 1.0s, second retry: 2.0s
    assert len(slept) == 2
    assert abs(slept[0] - 1.0) < 0.01
    assert abs(slept[1] - 2.0) < 0.01


def test_exception_filter_retries_matching():
    calls = []
    @retry(max_attempts=3, delay=0, exceptions=(ValueError,))
    def f():
        calls.append(1)
        raise ValueError("retry this")
    with pytest.raises(ValueError):
        f()
    assert len(calls) == 3


def test_exception_filter_propagates_nonmatching():
    calls = []
    @retry(max_attempts=5, delay=0, exceptions=(ValueError,))
    def f():
        calls.append(1)
        raise TypeError("don't retry")
    with pytest.raises(TypeError):
        f()
    assert len(calls) == 1


def test_preserves_return_value_after_retries():
    calls = []
    @retry(max_attempts=3, delay=0)
    def f():
        calls.append(1)
        if len(calls) < 2:
            raise ValueError()
        return 42
    assert f() == 42
